B.daw=new A.lu("SUG-FIN-12","Infla\xe7\xe3o pessoal","Abre o painel de cobran\xe7as e pre\xe7os, com compara\xe7\xf5es dispon\xedveis; os per\xedodos e exclus\xf5es dependem dos dados e ferramentas do painel.","/life/plus/money","Analisar pre\xe7os",!1)
