B.fyd=s(["Prioridade (inteiro; regras com prioridade mais alta s\xe3o avaliadas primeiro)","Grupo de condi\xe7\xf5es (E/OU, com subgrupos aninhados) sobre praticamente qualquer campo do movimento","Uma ou mais a\xe7\xf5es (definir categoria, entidade, projeto, ativo, empr\xe9stimo, adicionar etiqueta, etc.)","Descri\xe7\xe3o, notas"],t.s)
B.dlC=new A.cM("rules_screen","Regras autom\xe1ticas","Automa\xe7\xe3o","Lista as regras de classifica\xe7\xe3o autom\xe1tica da carteira ativa, ordenadas por prioridade (mais alta primeiro), com um resumo em texto das condi\xe7\xf5es e a\xe7\xf5es de cada uma. Permite criar, editar, ativar/desativar (interruptor) e eliminar regras; tocar numa regra abre um simulador contra um movimento real j\xe1 lan\xe7ado, para testar sem alterar nada.",B.b2e,B.b2e,B.hAc,B.ld,B.fyd,"O motor de regras em si (avaliar condi\xe7\xf5es/aplicar a\xe7\xf5es a um movimento) n\xe3o \xe9 chamado por este ecr\xe3 \u2014 corre automaticamente dentro de create_transaction e da importa\xe7\xe3o de extratos, no servidor. Este ecr\xe3 s\xf3 gere as regras e permite simular (simulate_rule) contra um movimento existente, sem gravar nada. Eliminar uma regra \xe9 um soft delete (define deleted_at).",'Nem o nome nem a valida\xe7\xe3o impedem gravar uma regra sem condi\xe7\xf5es ou sem a\xe7\xf5es \u2014 mas uma regra assim nunca corresponde/nunca faz nada, por isso o resumo mostra "(sem condi\xe7\xf5es)" quando \xe9 o caso.')
B.hyJ=s(["rule_logs","rules"],t.s)
B.dlu=new A.cM("rule_logs_screen","Hist\xf3rico de regras","Automa\xe7\xe3o",'Hist\xf3rico s\xf3 de leitura de cada avalia\xe7\xe3o real de uma regra contra um movimento (at\xe9 200 entradas mais recentes), com o nome da regra, o resultado (ex.: matched/applied/no_match) e a data. Acedido a partir do \xedcone de hist\xf3rico no ecr\xe3 "Regras autom\xe1ticas".',B.hyJ,B.p,B.p,B.p,B.p,null,"Cada linha de rule_logs \xe9 criada automaticamente pelo motor de regras no servidor (dentro de create_transaction/importa\xe7\xe3o) \u2014 este ecr\xe3 nunca escreve nada, s\xf3 l\xea. S\xf3 mostra regras da carteira ativa (junta rule_logs com rules pelo wallet_id).")
B.fac=s(["recurring_transactions","accounts","categories","entities","projects","assets","loans","cost_centers"],t.s)
B.hxF=s(["recurring_transactions"],t.s)
B.hC7=s(["Conta","Valor (maior que zero)","A cada (inteiro maior que zero)"],t.s)
B.fUP=s(["Categoria, entidade, projeto, ativo, empr\xe9stimo, atividade","Etiquetas, descri\xe7\xe3o, notas","Frequ\xeancia (di\xe1ria/semanal/mensal/anual, conforme RecurringTransaction.frequencies)","Data de fim"],t.s)
B.dl9=new A.cM("recurring_transactions_screen","Movimentos recorrentes","Automa\xe7\xe3o",'Lista os modelos de movimento recorrente da carteira ativa (rendas, subscri\xe7\xf5es, sal\xe1rios, presta\xe7\xf5es, etc.), ordenados pela pr\xf3xima data de execu\xe7\xe3o, com o interruptor para ativar/desativar cada um. O bot\xe3o "+" abre o formul\xe1rio completo para criar um modelo novo; tocar num existente abre-o para editar.',B.fac,B.hxF,B.p,B.hC7,B.fUP,'Este ecr\xe3 e o formul\xe1rio s\xf3 gerem os modelos (recurring_transactions) \u2014 nunca lan\xe7am movimentos diretamente. Uma tarefa agendada no servidor (run_recurring_transactions, corre todos os dias \xe0s 6h) \xe9 quem efetivamente cria o movimento e avan\xe7a next_run_date quando chega a data: no modo "Lan\xe7ar automaticamente" cria o movimento sozinha; no modo "Lembrar para confirmar" cria antes um lembrete para o utilizador confirmar manualmente. Passado o fim (end_date), o modelo \xe9 desativado automaticamente pela mesma tarefa. Eliminar um modelo \xe9 um soft delete que tamb\xe9m o desativa (deleted_at + is_active = false).','O formul\xe1rio de cria\xe7\xe3o/edi\xe7\xe3o est\xe1 em recurring_transaction_form_screen.dart ("/recurring-transactions/new"), com o mesmo conjunto de campos do formul\xe1rio de movimentos.')
B.hgm=s(["reminders","accounts","categories","entities","projects","assets","loans","cost_centers"],t.s)
B.hxW=s(["reminders"],t.s)
B.Jr=s(["T\xedtulo"],t.s)
B.h4n=s(["Data/hora do lembrete (por defeito, agora)","Conta, categoria, entidade, projeto, ativo, empr\xe9stimo, atividade","Valor, etiquetas, descri\xe7\xe3o, notas"],t.s)
B.dlL=new A.cM("reminders_screen","Lembretes","Automa\xe7\xe3o","Lista os lembretes da carteira ativa, agrupados em pendentes (primeiro, destacados a vermelho se em atraso) e resolvidos, ordenados pela data/hora do lembrete. Cada lembrete pendente permite registar o movimento associado diretamente (abre o formul\xe1rio de movimentos pr\xe9-preenchido) ou ignor\xe1-lo.",B.hgm,B.hxW,B.p,B.Jr,B.h4n,'"Registar movimento" leva para o formul\xe1rio de movimentos com os dados do lembrete pr\xe9-preenchidos, mas n\xe3o regista nada por si s\xf3 \u2014 a grava\xe7\xe3o do movimento \xe9 uma a\xe7\xe3o separada nesse formul\xe1rio. "Ignorar" e eliminar n\xe3o apagam a linha: mudam status (via setStatus) ou definem deleted_at, respetivamente. Editar a data/hora de um lembrete existente limpa notified_at, para a notifica\xe7\xe3o voltar a poder disparar no novo momento.','O formul\xe1rio de cria\xe7\xe3o/edi\xe7\xe3o est\xe1 em reminder_form_screen.dart ("/reminders/new").')
B.agG=s(["import_staging_rows","imports"],t.s)
B.dnf=new A.cM("banks_hub_screen","Bancos","Automa\xe7\xe3o",'Ecr\xe3 de entrada para tudo o que \xe9 liga\xe7\xe3o banc\xe1ria: um menu com tr\xeas atalhos \u2014 "Saldo banc\xe1rio" (consulta s\xf3 de leitura), "Movimentos por importar" (fila de revis\xe3o, com contador de pendentes) e "Liga\xe7\xe3o com Enable Banking" (ligar bancos e associar contas). N\xe3o l\xea nem escreve dados diretamente, s\xf3 conta os movimentos pendentes para o emblema.',B.agG,B.p,B.p,B.p,B.p,null,"Cada atalho tem o seu pr\xf3prio t\xf3pico de ajuda: banks_hub_screen s\xf3 cobre este menu; ver bank_connections_screen, bank_import_review_screen e bank_movements_consultation_screen para o que cada ecr\xe3 de destino faz.")
B.dmc=new A.cM("imports_hub_screen","Importa\xe7\xf5es","Automa\xe7\xe3o",'Ecr\xe3 de entrada para tudo o que traz movimentos para dentro da aplica\xe7\xe3o: importar extrato de ficheiro (CSV/OFX/QIF), extrato digital de cart\xe3o em PDF (escolhe a conta), digitalizar fatura, importar de print, remetentes banc\xe1rios por SMS, notifica\xe7\xf5es capturadas, modelos de importa\xe7\xe3o e hist\xf3rico de importa\xe7\xf5es \u2014 mais atalhos para "Movimentos por importar" (com contador de pendentes), Assistente de classifica\xe7\xe3o (com contador) e Dete\xe7\xe3o de duplicados. N\xe3o l\xea nem escreve dados diretamente, s\xf3 conta movimentos pendentes para os emblemas.',B.agG,B.p,B.p,B.p,B.p,null,"Cada atalho tem o seu pr\xf3prio t\xf3pico de ajuda; este ecr\xe3 s\xf3 cobre o menu. Assistente de classifica\xe7\xe3o e Dete\xe7\xe3o de duplicados continuam tamb\xe9m acess\xedveis a partir do ecr\xe3 de Movimentos, j\xe1 que atuam sobre movimentos j\xe1 importados.")
B.h2O=s(["bank_connections","bank_connection_accounts","accounts"],t.s)
